/// <summary>
/// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>
class METChangeItemStatusService
{
}

Method.Source:
    /// <summary>
    /// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange    
    /// </summary>
    /// <param name = "_metChangeItemStatusContract">data contract </param>
    public void changeStatus(METChangeItemStatusContract _metChangeItemStatusContract)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbds;
        QueryBuildRange         qbrItem, qbrSiteId;

        ItemId                  itemId  = _metChangeItemStatusContract.parmItemId();
        InventSiteId            siteId  = _metChangeItemStatusContract.parmInventSiteId();
        qbds        = query.addDataSource(tableNum(MetItemSiteSettingsSetup));

        if (itemId != '')
        {
            qbrItem     = qbds.addRange(fieldNum(MetItemSiteSettingsSetup,ItemId));
            qbrItem.value(queryValue(_metChangeItemStatusContract.parmItemId()));
        }

        if (siteId != '')
        {
            qbrSiteId   = qbds.addRange(fieldNum(MetItemSiteSettingsSetup,InventSiteId));
            qbrSiteId.value(queryValue(_metChangeItemStatusContract.parmInventSiteId()));
        }

        QueryRun                queryRun = new QueryRun(query);

        if(_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Active)
        {
            this.changeStatusToActive(queryRun);            
        }
        if(_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Discontinued)
        {
            this.changeStatusToDiscontinued(queryRun);
        }
        if(_metChangeItemStatusContract.parmMETItemStatus() == METConstants::Deleted)
        {
            this.changeStatusToDeleted(QueryRun);
        }
        
    }

    /// <summary>
    /// to change the item site level field called Item status to 'Deleted'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange    
    /// </summary>    
    /// <param name = "_queryRun"> query to select rcords </param>
    private void changeStatusToDeleted(QueryRun _queryRun)
    {
        while(_queryRun.next())
        {
            MetItemSiteSettingsSetup            metItemSiteSettingsSetup;            
            METSalesItemSubstitutionParentChild metSalesItemSubstitutionParentChild;

            metItemSiteSettingsSetup = _queryRun.get(tableNum(MetItemSiteSettingsSetup));

            select firstonly RecId from metSalesItemSubstitutionParentChild
                where metSalesItemSubstitutionParentChild.ChildItemID   == metItemSiteSettingsSetup.ItemId &&
                      metSalesItemSubstitutionParentChild.InventSiteId  == metItemSiteSettingsSetup.InventSiteId;

            boolean emptyInventValue        = this.isPhysicalInventoryValueZero(metItemSiteSettingsSetup.ItemId, metItemSiteSettingsSetup.InventSiteId);

            boolean isPOQtyOrTransQtyExist  = this.isPOQtyOrTransQtyExist(metItemSiteSettingsSetup.ItemId);

            if(!metSalesItemSubstitutionParentChild.RecId && 
                metItemSiteSettingsSetup.ItemStatus == METConstants::Discontinued && 
                emptyInventValue && 
                !isPOQtyOrTransQtyExist)
            {
                ReqItemTable    reqItemTable;
                InventDim       inventDimReq;
                InventDim       inventDim;

                inventDim.inventSiteId = metItemSiteSettingsSetup.InventSiteId;
                inventDim = InventDim::findDim(inventDim);
                
                select firstonly ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, RecId 
                    from reqItemTable
                    where reqItemTable.ReqPOType        == ReqPOType::Transfer
                    join RecId from inventDimReq
                        where reqItemTable.ItemId           == metItemSiteSettingsSetup.ItemId    &&
                                reqItemTable.CovInventDimId   == inventDimReq.inventDimId      &&                               
                                inventDimReq.InventSiteId     == metItemSiteSettingsSetup.InventSiteId;
                
                if(reqItemTable.RecId)
                {
                    InventLocation inventLocation;
                    
                    select firstonly inventLocation
                            where inventLocation.InventLocationId == reqItemTable.InventLocationIdReqMain;
                    
                    if(inventLocation)
                    {
                        MetItemSiteSettingsSetup    metItemSiteSettingsSetupSupplySite;
                        
                        select firstonly RecId 
                            from  metItemSiteSettingsSetupSupplySite
                            where metItemSiteSettingsSetupSupplySite.ItemId         == metItemSiteSettingsSetup.ItemId  &&
                                    metItemSiteSettingsSetupSupplySite.InventSiteId == inventLocation.InventSiteId      &&
                                    metItemSiteSettingsSetupSupplySite.ItemStatus   == METConstants::Deleted;
                        
                        if(metItemSiteSettingsSetupSupplySite.RecId)
                        {
                            this.updateStatusToDeletedMain(metItemSiteSettingsSetup, inventDim.inventDimId);                             
                        }
                    }
                }

                else
                {
                    this.updateStatusToDeletedMain(metItemSiteSettingsSetup, inventDim.inventDimId);
                }
                
            }
        }
    }

    /// <summary>
    /// to change the item site level field called Item status to 'Deleted'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetup"> MetItemSiteSettingsSetup record </param>
    /// <param name = "_inventDimId"> Inventory Dimension Id </param>    
    private void updateStatusToDeletedMain( MetItemSiteSettingsSetup    _metItemSiteSettingsSetup,
                                            InventDimId                 _inventDimId)
    {
        if(_metItemSiteSettingsSetup.RecId)
        {
            this.updateStatusToDeleted(_metItemSiteSettingsSetup, _inventDimId);
                                
            METSalesItemSubstitutionParentChild childItems;
                                                            
            while select ChildItemID, InventSiteId from childItems
                    where childItems.ParentItemID == _metItemSiteSettingsSetup.ItemId &&
                            childItems.InventSiteId == _metItemSiteSettingsSetup.InventSiteId
            {
                METItemSiteSettingsSetup itemSiteSettingsSetupForChildItems;
                                    
                select firstonly itemSiteSettingsSetupForChildItems
                        where itemSiteSettingsSetupForChildItems.ItemId           == childItems.ChildItemID  &&
                            itemSiteSettingsSetupForChildItems.InventSiteId     == childItems.InventSiteId;

                if (itemSiteSettingsSetupForChildItems)
                {
                    this.updateStatusToDeleted(itemSiteSettingsSetupForChildItems, _inventDimId, true);
                }
            }
        }
    }

    /// <summary>
    /// to change the item site level field called Item status to 'Deleted'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetup"> MetItemSiteSettingsSetup record </param>
    /// <param name = "_inventDimId"> Inventory Dimension Id </param>
    /// <param name = "_isChild"> Is child </param>
    private void updateStatusToDeleted( MetItemSiteSettingsSetup    _metItemSiteSettingsSetup, 
                                        InventDimId                 _inventDimId,
                                        boolean                     _isChild = false)
    {
        if (_metItemSiteSettingsSetup)
        {
            ttsbegin;

            _metItemSiteSettingsSetup.selectForUpdate(true);
            _metItemSiteSettingsSetup.ItemStatus         = METConstants::Deleted;
            _metItemSiteSettingsSetup.DeleteStatusDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            _metItemSiteSettingsSetup.doUpdate();

            InventItemInventSetup inventItemInventSetup     = InventItemInventSetup::find(_metItemSiteSettingsSetup.ItemId, _inventDimId);
            InventItemSalesSetup inventItemSalesSetup       = InventItemSalesSetup::find(_metItemSiteSettingsSetup.ItemId, _inventDimId);
                            
            if(inventItemInventSetup)
            {
                inventItemInventSetup.selectForUpdate(true);
                inventItemInventSetup.Stopped = true;
                inventItemInventSetup.doUpdate();
            }

            if(inventItemSalesSetup)
            {
                inventItemSalesSetup.selectForUpdate(true);
                inventItemSalesSetup.Stopped = true;
                inventItemSalesSetup.doUpdate();
            }

            if (_isChild)
            {
                InventItemPurchSetup inventItemPurchSetup       = InventItemPurchSetup::find(_metItemSiteSettingsSetup.ItemId, _inventDimId);
                            
                if(inventItemPurchSetup)
                {
                    inventItemPurchSetup.selectForUpdate(true);
                    inventItemPurchSetup.Stopped = true;
                    inventItemPurchSetup.doUpdate();
                }
            }

            ttscommit;
        }
    }

    /// <summary>
    /// To check whether open purchase line or transfer line exist.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange    
    /// </summary>
    /// <param name = "_itemId">Item </param>
    /// <returns>boolean value</returns>
    private boolean isPOQtyOrTransQtyExist(ItemId _itemId)
    {
        boolean             ret;
        PurchLine           purchLine;
        InventTransferLine  inventTransferLine;
        InventTransferTable inventTransferTable;

        select firstonly RecId from purchLine
            where purchLine.ItemId == _itemId &&
                  purchLine.PurchStatus  == PurchStatus::Backorder;
        
        select firstonly RecId from inventTransferLine
            where inventTransferLine.ItemId == _itemId 
            exists join inventTransferTable
                where inventTransferTable.TransferId == inventTransferLine.TransferId && 
                inventTransferTable.TransferStatus != InventTransferStatus::Shipped;
        
        if(purchLine || inventTransferLine)
        {
            ret = true;
        }

        return ret;
    }

/// <summary>
/// To check whether physical inventory fore the item is zero
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange     
/// </summary>
/// <param name = "_itemId">Item </param>
/// <param name = "_siteId">site </param>
/// <returns>boolean value</returns>
private boolean isPhysicalInventoryValueZero(ItemId _itemId, InventSiteId _siteId)
{
    boolean         ret;
    InventOnhand    inventOnhand;
    InventDim       inventDim;
    InventDimParm   inventDimParm;
    
    inventDim.InventSiteId = _siteId;
    inventDim = InventDim::findOrCreate(inventDim);
    inventDimParm.initFromInventDim(inventDim);
    inventOnhand = InventOnhand::newParameters(_itemId, inventDim, inventDimParm);
    
    if(!inventOnhand.availPhysical())
    {
        ret = true;
    }
    
    return ret;
}

    /// <summary>
    /// to change the item site level field called Item status to 'Discontinued'.
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange     
    /// </summary>
    /// <param name = "_queryRun"> query to select rcords </param>
    private void changeStatusToDiscontinued(QueryRun _queryRun)
    {
        while(_queryRun.next())
        {
            MetItemSiteSettingsSetup    metItemSiteSettingsSetup;
            metItemSiteSettingsSetup = _queryRun.get(tableNum(MetItemSiteSettingsSetup));
            
            if(metItemSiteSettingsSetup.DiscontinueDate != dateNull() && 
                metItemSiteSettingsSetup.DiscontinueDate <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) && 
                metItemSiteSettingsSetup.ItemStatus !=METConstants::Discontinued)
            {
                InventItemPurchSetup inventItemPurchSetup = InventItemPurchSetup::find(metItemSiteSettingsSetup.ItemId,metItemSiteSettingsSetup.InventDimId);
                
                if( inventItemPurchSetup )
                {
                    ttsbegin;
                    inventItemPurchSetup.selectForUpdate(true);;
                    inventItemPurchSetup.Stopped = true;
                    inventItemPurchSetup.doUpdate();

                    metItemSiteSettingsSetup.selectForUpdate(true);
                    metItemSiteSettingsSetup.ItemStatus = METConstants::Discontinued;
                    metItemSiteSettingsSetup.doUpdate();
                    ttscommit;
                }
            }
        }
    }

/// <summary>
/// to change the item site level field called Item status to 'Active'.
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange    
/// </summary>
/// <param name = "_queryRun"> query to select rcords </param>
private void changeStatusToActive(QueryRun _queryRun)
{
    
    while(_queryRun.next())
    {
        MetItemSiteSettingsSetup    metItemSiteSettingsSetup;
        metItemSiteSettingsSetup = _queryRun.get(tableNum(MetItemSiteSettingsSetup));
        InventSite  inventSite = InventSite::find(metItemSiteSettingsSetup.InventSiteId);
        
        if(metItemSiteSettingsSetup.ItemStatus == METConstants::NewStr && inventSite.METItemStatusUpdateTfrDependentSite)
        {
            ReqItemTable    reqItemTable;
            InventDim       inventDim;
            
            select firstonly ItemId,CovInventDimId,ReqPOType,InventLocationIdReqMain from reqItemTable
                    join RecId from inventDim
                    where reqItemTable.ItemId == metItemSiteSettingsSetup.ItemId    &&
                          reqItemTable.CovInventDimId == inventDim.inventDimId      &&
                          inventDim.InventSiteId == inventSite.SiteId;
            
            if(reqItemTable.ReqPOType == ReqPOType::Transfer)
            {
                InventLocation inventLocation;
                select firstonly inventLocation
                        where inventLocation.InventLocationIdReqMain == reqItemTable.InventLocationIdReqMain;
                
                if(inventLocation)
                {
                    MetItemSiteSettingsSetup    metItemSiteSettingsSetupSupplySite;
                    
                    select firstonly RecId 
                        from metItemSiteSettingsSetupSupplySite
                        where metItemSiteSettingsSetupSupplySite.ItemId         == metItemSiteSettingsSetup.ItemId  &&
                                metItemSiteSettingsSetupSupplySite.InventSiteId   == inventLocation.InventSiteId      &&
                                metItemSiteSettingsSetupSupplySite.ItemStatus     == METConstants::Active;
                    
                    if(metItemSiteSettingsSetupSupplySite)
                    {
                        ttsbegin;
                        metItemSiteSettingsSetup.selectForUpdate(true);
                        metItemSiteSettingsSetup.ItemStatus = METConstants::Active;
                        metItemSiteSettingsSetup.doUpdate();
                        ttscommit;
                    }
                }
            }
                               
        }
    }   
}
